use std::cmp::Ordering;

/// The supported dtypes, in increasing promotion order.
#[derive(Debug, Copy, Clone, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

impl NumpyDType {
    /// A numeric rank for promotion comparisons.
    fn rank(&self) -> u8 {
        match self {
            NumpyDType::Bool       => 0,
            NumpyDType::Int8       => 1,
            NumpyDType::Int16      => 2,
            NumpyDType::Int32      => 3,
            NumpyDType::Int64      => 4,
            NumpyDType::Float32    => 5,
            NumpyDType::Float64    => 6,
            NumpyDType::Complex64  => 7,
            NumpyDType::Complex128 => 8,
        }
    }
}

/// An operand: either a scalar or an array, each tagged with a dtype.
/// (We don't care about the actual data payload here.)
#[derive(Debug, Clone)]
pub enum NumpyOperand {
    Scalar { dtype: NumpyDType /*, value: ... */ },
    Array  { dtype: NumpyDType /*, shape: ..., data: ... */ },
}

impl NumpyOperand {
    /// Extract the declared dtype of this operand.
    pub fn dtype(&self) -> NumpyDType {
        match self {
            NumpyOperand::Scalar { dtype, .. } => *dtype,
            NumpyOperand::Array  { dtype, .. } => *dtype,
        }
    }
}

/// Given a non‐empty list of operands, compute the “promoted” dtype:
/// the one of highest rank present.
pub fn result_type(operands: Vec<NumpyOperand>) -> NumpyDType {
    // The input is guaranteed non‐empty, so `max_by_key(...).unwrap()` is safe.
    operands
        .into_iter()
        .map(|op| op.dtype())
        .max_by_key(|dt| dt.rank())
        .unwrap()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_simple_promotions() {
        let ops = vec![
            NumpyOperand::Scalar { dtype: NumpyDType::Bool },
            NumpyOperand::Array  { dtype: NumpyDType::Int8 },
            NumpyOperand::Scalar { dtype: NumpyDType::Float32 },
        ];
        assert_eq!(result_type(ops), NumpyDType::Float32);

        let ops2 = vec![
            NumpyOperand::Scalar { dtype: NumpyDType::Complex64 },
            NumpyOperand::Array  { dtype: NumpyDType::Float64 },
            NumpyOperand::Scalar { dtype: NumpyDType::Int32 },
        ];
        assert_eq!(result_type(ops2), NumpyDType::Complex64);

        let single = vec![ NumpyOperand::Array { dtype: NumpyDType::Int16 } ];
        assert_eq!(result_type(single), NumpyDType::Int16);
    }
}